function readName(req) {
  return String(req.query.name || 'default');
}
module.exports = { readName };

const { exec } = require('child_process');
const { readName } = require('./input');
function convert(req, done) {
  const name = readName(req);
  exec('convert ' + name + ' output.pdf', done);
}
module.exports = { convert };

const { spawn } = require('child_process');
function safeConvert(name, done) {
  spawn('convert', [name, 'output.pdf'], { shell: false }, done);
}
module.exports = { safeConvert };

